const rows = $input.all().map(i => i.json).filter(r => r.id != null);
const name = $('Execute Workflow Trigger').first().json.usecase_name;
const session_id = $('Execute Workflow Trigger').first().json.session_id;

if (rows.length < 1 || name == null) {
  return [{ json: {
    reply: `No active mappings found for ${name || 'this use case'}.`,
    session_id
  }}];
}

// Fixed the broken UTF-8 characters into clean, standard Markdown/text formatting
const lines = rows.map(r =>
  `• ID ${r.id}: value ${r.minvalue ?? '-'} to ${r.maxvalue ?? '-'} ➔ ` +
  `pulses ${r.minpulses}-${r.maxpulses}, ` +
  `intensity ${r.minintensity}-${r.maxintensity}, ` +
  `duration ${r.minduration}-${r.maxduration}ms, ` +
  `interval ${r.mininterval}-${r.maxinterval}ms`
).join('\n');

return [{ json: {
  reply: `Active mappings for ${name} (${rows.length} total):\n\n${lines}`,
  session_id
}}];

const input = $input.first().json;
const p = typeof input.params === 'string' 
  ? JSON.parse(input.params) 
  : (input.params ?? {});
const session_id = input.session_id;
const usecase_name = input.usecase_name;

const required = ['minvalue','maxvalue','minpulses','maxpulses',
                  'minintensity','maxintensity','minduration',
                  'maxduration','mininterval','maxinterval'];

const missing = required.filter(k => p[k] === undefined || p[k] === null);

if (missing.length > 0) {
  return [{ json: {
    valid: false,
    reply: `I need a few more details to add this mapping. Please provide: ${missing.join(', ')}.`,
    session_id
  }}];
}

return [{ json: {
  valid: true,
  session_id,
  usecase_name,
  usecase_id: input.usecase_id,
  minvalue:     p.minvalue,
  maxvalue:     p.maxvalue,
  minpulses:    p.minpulses,
  maxpulses:    p.maxpulses,
  minintensity: p.minintensity,
  maxintensity: p.maxintensity,
  minduration:  p.minduration,
  maxduration:  p.maxduration,
  mininterval:  p.mininterval,
  maxinterval:  p.maxinterval,
}}];

const rows = $input.all();
const session_id = $('Validate - add params').first().json.session_id;

if (rows.length === 0 || !rows[0].json.id) {
  return [{ json: {
    reply: `A mapping with those exact values already exists and is active. Use "list mappings" to see current IDs.`,
    session_id
  }}];
}

return [{ json: {
  reply: `Done. New mapping added with ID ${rows[0].json.id}.`,
  session_id
}}];

const reply = $input.first().json.text ?? '';
const session_id = $('Execute Workflow Trigger').first().json.session_id;
return [{ json: { reply, session_id } }];

const rows = $input.all().map(i => i.json);
const trigger = $('Execute Workflow Trigger').first().json;
return [{ json: {
  usecase_name:     trigger.usecase_name,
  session_id:       trigger.session_id,
  current_mappings: rows
}}];

const historical = $input.first().json;
const mappings = $('Package mappings').first().json.current_mappings;
const trigger = $('Execute Workflow Trigger').first().json;

return [{ json: {
  min_seen:         historical.min_seen,
  max_seen:         historical.max_seen,
  avg_seen:         historical.avg_seen,
  total_readings:   historical.total_readings,
  current_mappings: mappings,
  usecase_name:     trigger.usecase_name,
  session_id:       trigger.session_id
}}];

const raw = $input.first().json;
const input = raw.payload ?? raw;

let action = (input.action ?? '').toString().trim();
const msg = (input.message ?? '').toLowerCase();

if (!action) {
  if (msg.includes('suggest') || msg.includes('brainstorm') || msg.includes('idea') || msg.includes('recommend')) {
    action = 'brainstorm';
  } else if (msg.includes('change') || msg.includes('edit') || msg.includes('update') || msg.includes('modify')) {
    action = 'change';
  } else if (msg.includes('remove') || msg.includes('delete') || msg.includes('deactivate')) {
    action = 'remove';
  } else if (msg.includes('add') || msg.includes('create') || msg.includes('insert') || msg.includes('new mapping')) {
    action = 'add';
  } else {
    action = 'list';
  }
}

let params = {};
try {
  params = typeof input.params === 'string' ? JSON.parse(input.params) : (input.params ?? {});
} catch(e) {
  params = {};
}

if (action === 'add' && Object.keys(params).length === 0) {
  const nums = (input.message ?? '').match(/-?\d+(\.\d+)?/g)?.map(Number) ?? [];
  if (nums.length >= 10) {
    params = {
      minvalue:     nums[0], maxvalue:     nums[1],
      minpulses:    nums[2], maxpulses:    nums[3],
      minintensity: nums[4], maxintensity: nums[5],
      minduration:  nums[6], maxduration:  nums[7],
      mininterval:  nums[8], maxinterval:  nums[9]
    };
  }
}

return [{ json: {
  action,
  params,
  session_id:   input.session_id,
  usecase_id:   input.usecase_id,
  usecase_name: input.usecase_name,
  message:      input.message
}}];

const input = $input.first().json;
const params = typeof input.params === 'string'
  ? JSON.parse(input.params)
  : (input.params ?? {});

const session_id = input.session_id;
const usecase_id = Number(input.usecase_id);

if (!params.id) {
  return [{ json: {
    skip: true,
    reply: `Please specify which mapping ID to remove. Use "list mappings" to see current IDs.`,
    session_id
  }}];
}

return [{ json: {
  skip: false,
  action: 'remove',
  query: `UPDATE feedback_config_rules\nSET active = false\nWHERE id = $1 AND usecase_id = $2 AND active = true AND id <> 9999\nRETURNING id, 'remove' AS action;`,
  queryParams: [parseInt(params.id), usecase_id],
  session_id
}}];

const row = $input.first().json;
const session_id = $('Execute Workflow Trigger').first().json.session_id;

if (!row.id) {
  return [{ json: {
    reply: `No active mapping found with that ID for this usecase. Use "list mappings" to see current IDs.`,
    session_id
  }}];
}

const action = row.action ?? 'remove';
const reply = action === 'change'
  ? `Mapping ID ${row.id} has been updated.`
  : `Mapping ID ${row.id} has been deactivated.`;

return [{ json: { reply, session_id } }];

const input = $input.first().json;
let params = {};
try {
  params = typeof input.params === 'string' ? JSON.parse(input.params) : (input.params ?? {});
} catch(e) {
  params = {};
}

const session_id = input.session_id;
const usecase_id = Number(input.usecase_id);
const id = parseInt(params.id ?? params.mapping_id ?? params.mappingId);

if (!id || Number.isNaN(id)) {
  return [{ json: {
    valid: false,
    reply: `Please specify which mapping ID to change. Use "list mappings" to see current IDs.`,
    session_id
  }}];
}

if (!usecase_id || Number.isNaN(usecase_id)) {
  return [{ json: {
    valid: false,
    reply: `I could not resolve the use case ID for this mapping change. Please refresh use cases and try again.`,
    session_id
  }}];
}

const editable = ['minvalue','maxvalue','minpulses','maxpulses','minintensity','maxintensity','minduration','maxduration','mininterval','maxinterval'];
const updates = editable.filter(k => params[k] !== undefined && params[k] !== null && params[k] !== '');

if (updates.length === 0) {
  return [{ json: {
    valid: false,
    reply: `Please specify at least one mapping value to change for ID ${id}.`,
    session_id
  }}];
}

const assignments = updates.map((field, index) => `${field} = $${index + 1}`).join(', ');
const queryParams = updates.map(field => params[field]);
queryParams.push(id, usecase_id);

return [{ json: {
  valid: true,
  action: 'change',
  query: `UPDATE feedback_config_rules\nSET ${assignments}\nWHERE id = $${updates.length + 1} AND usecase_id = $${updates.length + 2} AND active = true\nRETURNING id, 'change' AS action;`,
  queryParams,
  session_id
}}];

const input = $input.first().json;
let p = {};
try {
  p = typeof input.params === 'string'
    ? JSON.parse(input.params)
    : (input.params ?? {});
} catch (e) {
  p = {};
}

const session_id = input.session_id;
const usecase_name = input.usecase_name;
const usecase_id = Number(input.usecase_id);

const mappingId = parseInt(
  p.id ?? p.mapping_id ?? p.mappingId ?? p.original_mapping_id ?? input.original_mapping_id
);

const userId = parseInt(p.user_id ?? input.user_id);

if (!mappingId || Number.isNaN(mappingId)) {
  return [{
    json: {
      valid: false,
      reply: `Please specify which mapping ID to change for this user. Use "list mappings" to see current IDs.`,
      session_id
    }
  }];
}

if (!userId || Number.isNaN(userId)) {
  return [{
    json: {
      valid: false,
      reply: `Please specify which user should receive this mapping change.`,
      session_id
    }
  }];
}

if (!usecase_id || Number.isNaN(usecase_id)) {
  return [{
    json: {
      valid: false,
      reply: `I could not resolve the use case ID for this mapping change. Please refresh use cases and try again.`,
      session_id
    }
  }];
}

const editable = [
  'minvalue',
  'maxvalue',
  'minpulses',
  'maxpulses',
  'minintensity',
  'maxintensity',
  'minduration',
  'maxduration',
  'mininterval',
  'maxinterval'
];

const updates = editable.filter(k => p[k] !== undefined && p[k] !== null && p[k] !== '');

if (updates.length === 0) {
  return [{
    json: {
      valid: false,
      reply: `Please specify at least one mapping value to change for mapping ID ${mappingId}.`,
      session_id
    }
  }];
}

return [{
  json: {
    valid: true,
    session_id,
    usecase_name,
    usecase_id,
    user_id: userId,
    mapping_id: mappingId,
    minvalue: p.minvalue ?? null,
    maxvalue: p.maxvalue ?? null,
    minpulses: p.minpulses ?? null,
    maxpulses: p.maxpulses ?? null,
    minintensity: p.minintensity ?? null,
    maxintensity: p.maxintensity ?? null,
    minduration: p.minduration ?? null,
    maxduration: p.maxduration ?? null,
    mininterval: p.mininterval ?? null,
    maxinterval: p.maxinterval ?? null
  }
}];

const incoming = $('Parse incoming').first().json;
const session_id = $('Execute Workflow Trigger').first().json.session_id;

// Explicitly pull the generated mapping ID from the correct DB insertion node
const dbInsertNode = $('DB - insert Duplicated mapping').first().json;
const newMappingId = dbInsertNode.id;

// Verify that we successfully got a mapping ID back from that specific step
if (!newMappingId) {
  return [{ json: {
    reply: `I ran into an issue isolating the mapping configuration. Please try again or verify the parameters.`,
    session_id
  }}];
}

const userId = incoming.user_id;
const oldMappingId = incoming.old_mapping_id ?? 'previous';

// Generate a targeted response for the single user override
const reply = `Successfully updated configuration for user ${userId}. They have been disconnected from mapping ID ${oldMappingId} and assigned to their own isolated mapping (ID ${newMappingId}).`;

return [{ json: { 
  reply, 
  session_id,
  user_id: userId,
  mapping_id: newMappingId
} }];
